import torch, torch.nn as nn, torch.nn.functional as F, numpy as np, time, json, math, argparse
from pathlib import Path
P=Path(__file__).parent
O,V=4,8
# Structured event triples; target is latest written value of each of two distinct queried owners.
def data(n,w,seed):
 r=np.random.default_rng(seed); owner=r.integers(O,size=(n,w)); val=r.integers(V,size=(n,w)); q=np.argsort(r.random((n,O)),axis=1)[:,:2]; owner[:,:4]=np.repeat(q,2,axis=1); order=np.argsort(r.random((n,w)),axis=1);owner=np.take_along_axis(owner,order,1);val=np.take_along_axis(val,order,1)
 x=np.zeros((n,w+2,3),np.int64);x[:,:w,1]=owner;x[:,:w,2]=val+1;x[:,w:,0]=1;x[:,w:,1]=q;ix=(np.arange(w)[None,None,:]*(owner[:,None,:]==q[:,:,None])).max(-1);y=np.take_along_axis(val,ix,1)
 cf=x.copy();cy=y.copy();cy[:,0]=(y[:,0]+r.integers(1,V,n))%V;cf[np.arange(n),ix[:,0],2]=cy[:,0]+1
 return tuple(torch.from_numpy(a) for a in (x,y,cf,cy))
# Affine scan equivalent to s_t=a_t*s_(t-1)+(1-a_t)*x_t; chunked for stability.
def scan(x,a,s=None):
 out=[]
 for x,a in zip(x.split(32,1),a.split(32,1)):
  p=a.cumprod(1);z=p*((1-a)*x/p).cumsum(1)
  if s is not None:z=z+p*s[:,None]
  s=z[:,-1];out.append(z)
 return torch.cat(out,1),s
class Cog(nn.Module):
 def __init__(self,d,pulse,core):
  super().__init__();self.w=d//4;self.pulse=pulse;self.core=core;w=self.w
  self.n=nn.LayerNorm(d);self.inp=nn.Linear(d,2*d);self.pub=nn.Linear(w,w);self.send=nn.Linear(w,2);self.recv=nn.Linear(w,2);self.up=nn.Linear(w,2*w);self.comp=nn.Linear(w,w);self.out=nn.Linear(d,d);self.n2=nn.LayerNorm(d);self.ff=nn.Sequential(nn.Linear(d,4*d),nn.GELU(),nn.Linear(4*d,d))
 def forward(self,h,state=None,no_pulse=False,no_core=False):
  B,T,D=h.shape;z,a=self.inp(self.n(h)).chunk(2,-1);z=z.tanh().reshape(B,T,4,self.w);a=(.6+.39*a.sigmoid()).reshape_as(z);r,rc=scan(z,a,None if state is None else state[0]);p=self.pub(r);g=self.send(r);s=self.recv(r)
  if self.pulse and not no_pulse:p0,p1=p.roll(1,2),p.roll(-1,2);g0,g1=g[...,0].roll(1,2),g[...,1].roll(-1,2)
  else:p0,p1=p,p;g0,g1=g[...,0],g[...,1]
  m=((g0+s[...,0]).sigmoid()[...,None]*p0+(g1+s[...,1]).sigmoid()[...,None]*p1)*.5;v,b=self.up(r+m).chunk(2,-1);u,uc=scan(v.tanh(),.6+.39*b.sigmoid(),None if state is None else state[1]);u=r+u;ctx=u.mean(2,keepdim=True).expand_as(u) if self.core and not no_core else u
  h=h+self.out((u*(1+self.comp(ctx).tanh())).reshape(B,T,D));return h+self.ff(self.n2(h)),(rc,uc)
class Tr(nn.Module):
 def __init__(self,d):
  super().__init__();self.n=nn.LayerNorm(d);self.qkv=nn.Linear(d,3*d);self.out=nn.Linear(d,d);self.n2=nn.LayerNorm(d);self.ff=nn.Sequential(nn.Linear(d,4*d),nn.GELU(),nn.Linear(4*d,d))
 def forward(self,h):
  B,T,D=h.shape;q,k,v=self.qkv(self.n(h)).reshape(B,T,3,4,D//4).permute(2,0,3,1,4).unbind(0);a=F.scaled_dot_product_attention(q,k,v,is_causal=True).transpose(1,2).reshape(B,T,D);h=h+self.out(a);return h+self.ff(self.n2(h))
class Model(nn.Module):
 def __init__(self,arm):
  super().__init__();self.arm=arm;d=200 if arm=='transformer' else 208;self.e=nn.Embedding(2,d);self.o=nn.Embedding(O,d);self.v=nn.Embedding(V+1,d);self.layers=nn.ModuleList([Tr(d) if arm=='transformer' else Cog(d,arm in ('pulse','full'),arm in ('core','full')) for _ in range(2)]);self.head=nn.Sequential(nn.LayerNorm(d),nn.Linear(d,V));self.register_buffer('freq',torch.exp(-math.log(10000)*torch.arange(0,d,2)/d))
 def forward(self,x,state=None,offset=0,return_state=False,no_pulse=False,no_core=False):
  a=torch.arange(offset,offset+x.shape[1],device=x.device)[:,None]*self.freq;pos=torch.stack([a.sin(),a.cos()],-1).flatten(-2);h=self.e(x[:,:,0])+self.o(x[:,:,1])+self.v(x[:,:,2])+.2*pos;new=[]
  for i,l in enumerate(self.layers):
   if self.arm=='transformer':h=l(h)
   else:h,c=l(h,None if state is None else state[i],no_pulse,no_core);new.append(c)
  z=self.head(h);return (z,new) if return_state else z
@torch.no_grad()
def score(m,d,**kw):
 x,y,cf,cy=d;z=[];c=[];nll=0
 for a,b,k,e in zip(x.split(64),y.split(64),cf.split(64),cy.split(64)):
  logits=m(a,**kw)[:,-2:];z.append(logits.argmax(-1)==b);c.append(m(k,**kw)[:,-2:].argmax(-1)==e);nll+=F.cross_entropy(logits.flatten(0,1),b.flatten(),reduction='sum').item()
 z=torch.cat(z);c=torch.cat(c);return {'n':len(y),'acc':z.float().mean().item(),'pair':z.all(1).float().mean().item(),'counterfactual_pair':(z.all(1)&c.all(1)).float().mean().item(),'nll':nll/(2*len(y))}
def train(arm,seed,steps,batch):
