 for i,(a,b) in enumerate(zip(x.split(batch),y.split(batch)),1):
  opt.zero_grad(set_to_none=True);z=m(a)[:,-2:];loss=F.cross_entropy(z.flatten(0,1),b.flatten());loss.backward();nn.utils.clip_grad_norm_(m.parameters(),1.);opt.step()
  if i in (1,steps//2,steps):history.append([i,loss.item()])
 elapsed=time.perf_counter()-start;m.eval();r={'arm':arm,'seed':seed,'params':params,'steps':steps,'batch':batch,'train_events':steps*batch*10,'train_seconds':elapsed,'history':history,'iid':score(m,val),'long':score(m,long)}
 if arm=='full':r['disable_pulse']=score(m,val,no_pulse=True);r['disable_core']=score(m,val,no_core=True)
 if arm!='transformer':
  with torch.no_grad():
   x=long[0][:8];whole,_=m(x,return_state=True);state=None;parts=[]
   for j in range(x.shape[1]):
    z,state=m(x[:,j:j+1],state=state,offset=j,return_state=True);parts.append(z)
   r['stream_max_error']=(whole-torch.cat(parts,1)).abs().max().item();r['state_bytes']=sum(z[0].numel()*z.element_size() for layer in state for z in layer);r['causal_max_error']=(whole[:,:10]-m(x[:,:10])).abs().max().item()
 with torch.no_grad():
  x=val[0][:32];m(x);start=time.perf_counter()
  for _ in range(10):m(x)
  r['forward_events_s']=10*x.shape[0]*x.shape[1]/(time.perf_counter()-start)
 print(json.dumps(r),flush=True);return r
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--steps',type=int,default=100);p.add_argument('--batch',type=int,default=16);p.add_argument('--seeds',type=int,nargs='+',default=[173]);p.add_argument('--arms',nargs='+',default=['native','pulse','core','full','transformer']);p.add_argument('--threads',type=int,default=2);a=p.parse_args();torch.set_num_threads(a.threads);torch.set_num_interop_threads(1)
 for seed in a.seeds:
  for arm in a.arms:
   r=train(arm,seed,a.steps,a.batch)
   with open(P/'results.jsonl','a') as f:f.write(json.dumps(r)+'\n')

