  else:
   w,rp,write=g.split([self.k,self.k,1],-1);w=w.softmax(-1);rp=rp.softmax(-1)
   if mode=='hard' or (mode=='train' and self.arm=='hard'):
    hw=F.one_hot(w.argmax(-1),self.k).to(w.dtype);hr=F.one_hot(rp.argmax(-1),self.k).to(rp.dtype);w=hw+(w-w.detach()) if self.training else hw;rp=hr+(rp-rp.detach()) if self.training else hr
   if ab=='uniform':w=torch.full_like(w,1/self.k);rp=torch.full_like(rp,1/self.k)
   gate=.8*write.sigmoid()*w; mseq,ms=scan(v[:,:,None,:].expand(-1,-1,self.k,-1),1-gate[...,None],None if state is None else state[1]);m=(mseq*rp[...,None]).sum(-2);diag=(w.detach(),rp.detach(),gate.detach()) if stats else None
