  self.emb=nn.Embedding(V,d);self.layers=nn.ModuleList([(Tr(d) if arm=='transformer' else Cog(d,arm)) for _ in range(2)]);self.norm=nn.LayerNorm(d);self.head=nn.Linear(d,V,bias=False);self.head.weight=self.emb.weight;self.register_buffer('freq',torch.exp(-math.log(10000)*torch.arange(0,d,2)/d));nn.init.normal_(self.emb.weight,std=.02)
